import { GoogleGenAI, Type, ThinkingLevel } from '@google/genai';
import { AbnormalFlag } from './ml-pipeline.ts';

export interface ClinicalExplanation {
  risk_level: 'low' | 'moderate' | 'high';
  key_factors: string[];
  recommendation: string;
  disclaimer: string;
  source?: 'gemini-3.8-flash' | 'clinical-heuristics-engine';
}

const DEFAULT_DISCLAIMER =
  'CLINICAL DECISION SUPPORT NOTICE: This assessment is an automated predictive estimate generated by a machine learning model paired with an AI clinical communication agent. It is NOT a definitive medical diagnosis and does not establish a physician-patient relationship. All recommendations must be reviewed, corroborated with venous blood lab tests (HbA1c, 2-hr OGTT), and validated by a licensed physician before clinical action.';

// In-memory cache to prevent redundant API calls for identical clinical states
const explanationCache = new Map<string, ClinicalExplanation>();

export function generateFallbackExplanation(
  probability: number,
  flags: AbnormalFlag[]
): ClinicalExplanation {
  const risk_level: 'low' | 'moderate' | 'high' =
    probability >= 0.7 ? 'high' : probability >= 0.4 ? 'moderate' : 'low';

  const key_factors: string[] = [];

  if (flags.length > 0) {
    for (const flag of flags) {
      key_factors.push(
        `${flag.feature} is ${flag.status} at ${flag.value} ${flag.unit} (reference range: ${flag.normalRange}). ${flag.clinicalInterpretation}`
      );
    }
  } else {
    key_factors.push(
      'Routine biomarker values (Glucose, Diastolic BP, BMI) fall within baseline normal clinical reference intervals.'
    );
  }

  let recommendation = '';
  if (risk_level === 'high') {
    recommendation =
      'Immediate clinical follow-up indicated: Order diagnostic venous fasting plasma glucose and laboratory HbA1c test within 7–14 days. Evaluate metabolic syndrome comorbidities, review cardiovascular risks, and refer patient to certified diabetes care & education specialist (CDCES).';
  } else if (risk_level === 'moderate') {
    recommendation =
      'Schedule routine metabolic screening within 3–6 months. Initiate structured dietary counseling focusing on low glycemic index nutrition, 150 minutes/week of moderate physical activity, and repeat fasting glucose evaluation.';
  } else {
    recommendation =
      'Maintain standard preventative care and annual metabolic health checkup. Reinforce healthy balanced lifestyle habits and weight maintenance.';
  }

  return {
    risk_level,
    key_factors,
    recommendation,
    disclaimer: DEFAULT_DISCLAIMER,
    source: 'clinical-heuristics-engine'
  };
}

export async function explainDiagnosis(
  probability: number,
  flags: AbnormalFlag[]
): Promise<ClinicalExplanation> {
  const cacheKey = `${probability.toFixed(2)}_${flags.map((f) => `${f.feature}:${f.status}:${f.value}`).join('|')}`;
  if (explanationCache.has(cacheKey)) {
    return explanationCache.get(cacheKey)!;
  }

  const apiKey = process.env.GEMINI_API_KEY;

  if (!apiKey || apiKey === 'MY_GEMINI_API_KEY') {
    const fallback = generateFallbackExplanation(probability, flags);
    explanationCache.set(cacheKey, fallback);
    return fallback;
  }

  try {
    const ai = new GoogleGenAI({
      apiKey,
      httpOptions: {
        headers: {
          'User-Agent': 'aistudio-build'
        }
      }
    });

    const promptPayload = {
      model_probability: probability,
      probability_percentage: `${(probability * 100).toFixed(1)}%`,
      deterministic_abnormal_flags: flags.map((f) => ({
        feature: f.feature,
        status: f.status,
        value: f.value,
        unit: f.unit,
        normal_range: f.normalRange,
        severity: f.severity,
        clinical_interpretation: f.clinicalInterpretation
      }))
    };

    const systemInstruction = `You are a clinical communication assistant embedded in the AI Health Copilot Pro decision support system.
CRITICAL CLINICAL SAFETY CONSTRAINTS:
1. You are a clinical communication assistant, NOT a diagnosing physician.
2. Reason ONLY and STRICTLY from the provided deterministic abnormal flags and model probability.
3. NEVER invent or hallucinate clinical features, lab values, or patient history not present in the input payload.
4. Output concise, professional, evidence-based physician-grade language.
5. Always return a strong, unambiguous clinical disclaimer.`;

    const generatePromise = ai.models.generateContent({
      model: 'gemini-3.8-flash',
      contents: `Generate a structured clinical risk communication based strictly on the following deterministic ML output:\n${JSON.stringify(
        promptPayload,
        null,
        2
      )}`,
      config: {
        systemInstruction,
        responseMimeType: 'application/json',
        thinkingConfig: {
          thinkingLevel: ThinkingLevel.LOW
        },
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            risk_level: {
              type: Type.STRING,
              description: 'Risk category: low, moderate, or high'
            },
            key_factors: {
              type: Type.ARRAY,
              items: { type: Type.STRING },
              description: 'Key contributing clinical factors based strictly on the provided abnormal flags'
            },
            recommendation: {
              type: Type.STRING,
              description: 'Actionable clinical recommendation for next clinical steps, lab work, or lifestyle'
            },
            disclaimer: {
              type: Type.STRING,
              description: 'Formal medical decision support disclaimer statement'
            }
          },
          required: ['risk_level', 'key_factors', 'recommendation', 'disclaimer']
        }
      }
    });

    // Allow generous 20-second timeout for cloud generation
    const timeoutPromise = new Promise<never>((_, reject) =>
      setTimeout(() => reject(new Error('Gemini API timeout (20s exceeded)')), 20000)
    );

    const response = await Promise.race([generatePromise, timeoutPromise]);

    const text = response.text;
    if (!text) {
      const fallback = generateFallbackExplanation(probability, flags);
      explanationCache.set(cacheKey, fallback);
      return fallback;
    }

    const parsed = JSON.parse(text) as ClinicalExplanation;

    const result: ClinicalExplanation = {
      risk_level:
        parsed.risk_level === 'high' || parsed.risk_level === 'moderate' || parsed.risk_level === 'low'
          ? parsed.risk_level
          : probability >= 0.7
          ? 'high'
          : probability >= 0.4
          ? 'moderate'
          : 'low',
      key_factors:
        Array.isArray(parsed.key_factors) && parsed.key_factors.length > 0
          ? parsed.key_factors
          : generateFallbackExplanation(probability, flags).key_factors,
      recommendation:
        parsed.recommendation || generateFallbackExplanation(probability, flags).recommendation,
      disclaimer: parsed.disclaimer || DEFAULT_DISCLAIMER,
      source: 'gemini-3.8-flash'
    };

    explanationCache.set(cacheKey, result);
    return result;
  } catch (err: any) {
    console.warn('Gemini clinical explanation fallback activated:', err?.message || err);
    const fallback = generateFallbackExplanation(probability, flags);
    explanationCache.set(cacheKey, fallback);
    return fallback;
  }
}
